                    process.env.EVOLVE_FORCE_SIGNAL = 'force_innovation_after_repair_loop';
                    forwardLogToFeishu(`[Wrapper] 🔄 Repair Loop Detected (${repairCount}x). Forcing Innovation...`, 'WARNING');
                } else {
