                                        // If keys are unquoted (e.g. { task: "..." }), we need to quote them for JSON.parse.
                                        if (!rawJson.includes('"task":') && !rawJson.includes("'task':")) {
                                             rawJson = rawJson.replace(/([{,]\s*)([a-zA-Z0-9_]+)(\s*:)/g, '$1"$2"$3');
